/*	Read the TRIGGER, not $input. Config sits between the two and does not pass
	other fields through, so $input here is the config values and the failure
	payload has already gone.

	The payload carries workflow and execution metadata only, never the failing
	workflow's data, so the reason has to be fetched back from the execution
	itself. That is the next node's job.

	The error sits under execution on some n8n versions and at the top level on
	others, so both are read.	*/

const payload_obj = $('A workflow failed').first().json ?? {};
const execution_obj = payload_obj.execution ?? {};
const workflow_obj = payload_obj.workflow ?? {};
const error_obj = payload_obj.error ?? execution_obj.error ?? {};

/*	The trigger stamps the failure in epoch milliseconds, not ISO.	*/
const stamp_var = error_obj.timestamp ?? null;
let failedAt_str = new Date().toISOString();
if (typeof stamp_var === 'number')
{
	failedAt_str = new Date(stamp_var).toISOString();
} else if (typeof stamp_var === 'string' && stamp_var !== '') {
	failedAt_str = stamp_var;
}

/*	execution.url is NOT used: it can read localhost:5678, because
	a failure has no incoming request to build a host from. The human link is
	built from N8N_UI_BASE_URL instead.	*/

return [{
	json:
	{
		failed_at: failedAt_str,
		workflow_id: String(workflow_obj.id ?? ''),
		workflow_name: String(workflow_obj.name ?? 'unknown workflow'),
		execution_id: String(execution_obj.id ?? ''),
		execution_mode: String(execution_obj.mode ?? ''),
		failed_node: String((error_obj.node ?? {}).name ?? execution_obj.lastNodeExecuted ?? ''),
		message: String(error_obj.message ?? error_obj.description ?? 'Unknown error'),
		stack: String(error_obj.stack ?? '')
	}
}];

/*	One failure, written two ways.

	Administrate gets plain language: what failed and why. Which node stopped,
	the run mode, the stack and the raw error are n8n internals that mean
	nothing to Administrate users, so they go in the data table instead, which
	only somebody with n8n access can open.

	Everything here degrades rather than throws. A handler that throws produces
	the one failure nobody ever hears about.	*/

const config_obj = $('Config').first().json;
const extract_obj = $('Extract failure').first().json;
const fetched_obj = $input.first().json ?? {};

let failedNode_str = extract_obj.failed_node;
let reason_str = extract_obj.message;

const resultData_obj = (fetched_obj.data ?? {}).resultData ?? {};
const runData_obj = resultData_obj.runData ?? null;
const resultError_obj = resultData_obj.error ?? null;

if (resultError_obj !== null)
{
	reason_str = String(resultError_obj.message ?? reason_str);
	failedNode_str = String((resultError_obj.node ?? {}).name ?? failedNode_str);
}
if (failedNode_str === '' && resultData_obj.lastNodeExecuted !== undefined)
{
	failedNode_str = String(resultData_obj.lastNodeExecuted);
}

const nodesRun_int = runData_obj === null ? 0 : Object.keys(runData_obj).length;
const fetchedOk_bln = runData_obj !== null || resultError_obj !== null;

const executionUrl_str = String(config_obj.N8N_UI_BASE_URL)
	+ '/workflow/' + extract_obj.workflow_id
	+ '/executions/' + extract_obj.execution_id;

/*	The workflow name minus any parenthetical (e.g. "(shared)"), which is an
	n8n-side label rather than something Administrate users need.	*/
const stage_str = String(extract_obj.workflow_name).split('(')[0].trim();

/*	Administrate renders one detail per column and expects every group to hold
	exactly two, a label and a value, or the entry comes out ragged.	*/
const groups_ary =
[
	{ details: [{ type: 'text', value: 'Failed at' }, { type: 'text', value: stage_str }] },
	{ details: [{ type: 'text', value: 'Reason' }, { type: 'text', value: reason_str }] },
	{ details: [{ type: 'text', value: 'When' }, { type: 'text', value: extract_obj.failed_at }] }
];

const details_obj =
{
	failed_node: failedNode_str,
	execution_mode: extract_obj.execution_mode,
	nodes_run: nodesRun_int,
	execution_fetched: fetchedOk_bln,
	stack: extract_obj.stack
};

const notifyBody_str = stage_str + ' failed.\n\n'
	+ 'Reason: ' + reason_str + '\n'
	+ 'Failed node: ' + (failedNode_str === '' ? 'not reported' : failedNode_str) + '\n'
	+ 'When: ' + extract_obj.failed_at + '\n\n'
	+ 'Execution: ' + executionUrl_str;

return [{
	json:
	{
		failed_at: extract_obj.failed_at,
		workflow_name: extract_obj.workflow_name,
		workflow_id: extract_obj.workflow_id,
		execution_id: extract_obj.execution_id,
		execution_url: executionUrl_str,
		failed_node: failedNode_str,
		message: reason_str,
		stage: stage_str,
		details: JSON.stringify(details_obj),
		log_message: stage_str + ' failed: ' + reason_str,
		log_payload: JSON.stringify({ groups: groups_ary }),
		notify_subject: 'n8n failure: ' + extract_obj.workflow_name,
		notify_body: notifyBody_str
	}
}];
